1630	/// Шаг драйвера на одном сигнале — всё, что требует движка: часы к `t0`,
1631	/// проверка позиции, вход, круг, страховка остатка. Общий для сплошного
1632	/// прогона (`drive_bounce`) и прогона по сетапам (`drive_bounce_windowed`):
1633	/// различие только в том, откуда берётся движок, — иначе это была бы вторая
1634	/// стратегия.
1635	#[derive(Clone)]
1636	enum SignalStep {
1637	    /// Часы не дошли до `t0`: запись кончилась.
1638	    EndOfData,
1639	    /// Книга не была готова в момент касания — попытки не было.
1640	    NotSubmitted { idle_ns: i64 },
1641	    Submitted {
1642	        crossed: bool,
1643	        spread: Option<f64>,
1644	        outcome: RoundOutcome,
1645	        /// `Some(ended)` — остаток позиции закрывали по рынку; `ended` —
1646	        /// запись кончилась в процессе.
1647	        residual: Option<bool>,
1648	        /// Часы стороны в момент, когда стратегия снова `Idle` (граница
1649	        /// шага опроса после выхода или подтверждённой отмены): до него
1650	        /// форма **занята** для любого сигнала.
1651	        idle_ns: i64,
1652	        /// F8b (В5/Р2): сколько раз круг пережил потолок ожидания
1653	        /// подтверждения отмены лимитки выхода (`CANCEL_WAIT_NS`).
1654	        exit_cancel_timeouts: u64,
1655	        /// F8c (К1): исполнения заявок-сирот (после потолка) за круг.
1656	        orphan_fills: u64,
1657	    },
1658	}
1659	
1660	fn drive_signal<B, MD>(
1661	    bot: &mut B,
1662	    asset_no: usize,
1663	    sig: &BounceSignal,
1664	    cfg: &DriveConfig,
1665	    next_id: &mut u64,
1666	    carry: &mut OrphanCarry,
1667	) -> Result<SignalStep, B::Error>
1668	where
1669	    B: Bot<MD>,
1670	    MD: MarketDepth,
1671	{
1672	    let now = bot.current_timestamp();
1673	    if sig.t0_ns > now {
1674	        if bot.elapse(sig.t0_ns - now)? == ElapseResult::EndOfData {
1675	            return Ok(SignalStep::EndOfData);
1676	        }
1677	        // Сделки до постановки входа к пути исполнения не относятся (F3):
1678	        // буфер чистится, детектор `run_round` видит только шаг исполнения.
1679	        bot.clear_last_trades(Some(asset_no));
1680	    }
1681	    // Проверки «позиция уже открыта» по `Bot::position` здесь нет: с F4
1682	    // (В-78) вход исполняется частично, а `Bot::position` крейта ведёт
1683	    // позицию только по `Filled` (находка F3) — после первого же частичного
1684	    // входа она врёт со знаком, и такая проверка объявила бы «занятыми» все
1685	    // оставшиеся сигналы суток. Занятость ведёт `idle_ns` — момент, когда
1686	    // стратегия вернулась в `Idle` со **своей** позицией, равной нулю
1687	    // (`drive_bounce_with`), и в обоих драйверах он один и тот же (гейт
1688	    // «те же круги» на `lob bounce-grid --driver full|setups`).
1689	
1690	    let qty = sig.qty.unwrap_or(cfg.order_qty);
1691	    debug_assert!(qty > 0.0, "размер круга обязан быть положительным: {qty}");
1692	    let mut state = StrategyState::with_plan(asset_no, sig.sigma, qty, *next_id, sig.plan);
1693	    *next_id = next_id.saturating_add(ID_STRIDE);
1694	    // F8c: сироты прошлого круга живут дальше в новом состоянии — уборка
1695	    // (повтор снятия, учёт исполнения) идёт с первого события этого круга.
1696	    state.inherit_orphans(*carry);
1697	
1698	    let (entry_id, side) = match on_event(bot, &mut state)? {
1699	        Action::EntrySubmitted { order_id, side, .. } => (order_id, side),
1700	        _ => {
1701	            *carry = state.take_orphans();
1702	            return Ok(SignalStep::NotSubmitted {
1703	                idle_ns: bot.current_timestamp(),
1704	            });
1705	        }
1706	    };
1707	    // Замер механизма отказа (таск 38): в момент отправки входа смотрим,
1708	    // пересекает ли его цена спред и каков спред. Пост-онли такую заявку
1709	    // отвергает, обычный лимит — исполняет как тейкер.
1710	    let mut crossed = false;
1711	    let mut spread = None;
1712	    if let Some(entry_px) = entry_market_px(sig.plan) {
1713	        let d = bot.depth(asset_no);
1714	        let (bid, ask) = (d.best_bid(), d.best_ask());
1715	        if bid.is_finite() && ask.is_finite() && bid > 0.0 && ask > 0.0 {
1716	            crossed = match side {
1717	                HbtSide::Buy => ask <= entry_px,
1718	                _ => bid >= entry_px,
1719	            };
1720	            spread = Some(ask - bid);
1721	        }
1722	    }
1723	
1724	    let (outcome, residual_left) =
1725	        run_round(bot, asset_no, &mut state, entry_id, legs_of(sig.plan), side)?;
1726	    if matches!(outcome, RoundOutcome::EndOfData) {
1727	        *carry = state.take_orphans();
1728	        return Ok(SignalStep::Submitted {
1729	            crossed,
1730	            spread,
1731	            outcome,
1732	            residual: None,
1733	            idle_ns: bot.current_timestamp(),
1734	            exit_cancel_timeouts: state.exit_cancel_timeouts(),
1735	            orphan_fills: state.orphan_fills(),
1736	        });
1737	    }
1738	    // Страховка (2026-09-18): круг кончился, а позиция осталась (например,
1739	    // `Inconsistent`) — закрыть по рынку и посчитать, иначе все дальнейшие
1740	    // сигналы молча «заняты» и остаток суток не считается вовсе. Размер
1741	    // остатка — **своя** позиция стратегии (F4/В-78): `Bot::position` крейта
1742	    // частичного исполнения не видит (находка F3), и по ней страховка
1743	    // закрывала бы мнимый остаток, помечая честный круг `incomplete`.
1744	    let mut residual = None;
1745	    let mut left = signed_residual(side, residual_left);
1746	    if left != 0.0 {
1747	        let mut ended = false;
1748	        while left != 0.0 {
1749	            let id = *next_id;
1750	            *next_id = next_id.saturating_add(1);
1751	            match flatten_residual(bot, asset_no, id, left)? {
1752	                FlattenOutcome::Flat => break,
1753	                FlattenOutcome::Retry { left: rest } => left = rest,
1754	                FlattenOutcome::EndOfData => {
1755	                    ended = true;
1756	                    break;
1757	                }
1758	            }
1759	        }
1760	        residual = Some(ended);
1761	        if ended {
1762	            *carry = state.take_orphans();
1763	            return Ok(SignalStep::Submitted {
1764	                crossed,
1765	                spread,
1766	                outcome,
1767	                residual,
1768	                idle_ns: bot.current_timestamp(),
1769	                exit_cancel_timeouts: state.exit_cancel_timeouts(),
1770	                orphan_fills: state.orphan_fills(),
1771	            });
1772	        }
1773	    }
1774	    bot.clear_inactive_orders(Some(asset_no));
1775	    *carry = state.take_orphans();
1776	    Ok(SignalStep::Submitted {
1777	        crossed,
1778	        spread,
1779	        outcome,
1780	        residual,
1781	        idle_ns: bot.current_timestamp(),
1782	        exit_cancel_timeouts: state.exit_cancel_timeouts(),
1783	        orphan_fills: state.orphan_fills(),
1784	    })
1785	}
1786	
1787	/// Память кругов сетки (G10, владелец 2026-09-23: «ускорить бэктест без потерь»). В прогоне по
1788	/// сетапам круг — свежий движок над окном `t0`: его итог задают окно, сторона, план и настройка
1789	/// драйвера, а не прежние круги формы и не набор (`--set` только выбирает сигналы). Поэтому круг

