1931	/// Запас горизонта развёртки круга сверх `entry_ttl + deadline` плана (Р6): подтверждения и отмены после
1932	/// дедлайна. Точность не зависит от него — короткий горизонт ловит проверка и пересчитывает круг.
1933	const HORIZON_MARGIN_NS: i64 = 60_000_000_000;
1934	
1935	/// Горизонт первой попытки развёртки (Р6-поправка, 26.09): большинство кругов (вход не исполнен, быстрый
1936	/// выход) кончается за минуты, а полный горизонт плана — часы (`entry_ttl` + дедлайн); развёртка на весь
1937	/// горизонт на каждый сигнал делала касания ×5 медленнее старого пути (CRV 22.09, 8 форм: 12 → 71 с).
1938	/// Первая попытка — не дальше этого, вторая — сразу полный горизонт, дальше удвоение: лишняя работа
1939	/// длинного круга ограничена первой попыткой. Точность от числа не зависит (проверка конца данных), только
1940	/// время; значение — замер `prof/r6fix.log` (findings T-23).
1941	const FIRST_HORIZON_NS: i64 = 300_000_000_000;
1942	
1943	// Тестовая подмена начального горизонта развёртки (условие Судьи 2 к Р6): искусственно малый горизонт
1944	// заставляет пересчитывать почти каждый круг — итог обязан остаться побайтно тем же.
1945	#[cfg(test)]
1946	thread_local! {
1947	    pub(crate) static HORIZON_SPAN_OVERRIDE_NS: std::cell::Cell<Option<i64>> =
1948	        const { std::cell::Cell::new(None) };
1949	}
1950	
1951	fn horizon_span_ns(plan: &TradePlan) -> i64 {
1952	    #[cfg(test)]
1953	    if let Some(v) = HORIZON_SPAN_OVERRIDE_NS.with(std::cell::Cell::get) {
1954	        return v.max(1);
1955	    }
1956	    plan.round_span_ns()
1957	        .saturating_add(HORIZON_MARGIN_NS)
1958	        .max(1)
1959	}
1960	
1961	fn drive_bounce_with<B, MD, S>(
1962	    asset_no: usize,
1963	    signals: &[BounceSignal],
1964	    cfg: &DriveConfig,
1965	    mut memo: Option<&mut RoundMemo>,
1966	    mut source: S,
1967	) -> Result<BounceRun, B::Error>
1968	where
1969	    B: Bot<MD>,
1970	    MD: MarketDepth,
1971	    // Источник круга: сигнал, номер попытки (Р6 — пересчёт с удвоенным горизонтом развёртки) и шаг
1972	    // стратегии; отдаёт шаг и «данных хватило» (`false` — круг пересчитывается с восстановленными
1973	    // номерами заявок и переносом сирот, как будто первой попытки не было).
1974	    S: FnMut(
1975	        &BounceSignal,
1976	        u32,
1977	        &mut dyn FnMut(&mut B) -> Result<SignalStep, B::Error>,
1978	    ) -> Result<Option<(SignalStep, bool)>, B::Error>,
1979	{
1980	    let mut order: Vec<BounceSignal> = signals.to_vec();
1981	    order.sort_by_key(|s| s.t0_ns);
1982	    let profile = signals.first().map(|s| s.profile).unwrap_or(0);
1983	    let mut fills: Vec<Fill> = Vec::new();
1984	    let mut misses = MissLedger::default();
1985	    let mut observations: Vec<FillObservation> = Vec::new();
1986	    let mut exits = ExitTally::default();
1987	    let mut entry_rejected: u64 = 0;
1988	    let mut rejected_postonly: u64 = 0;
1989	    let mut entry_crossed: u64 = 0;
1990	    // Снятия неисполненного входа по причинам (F5, В-74) — в `forms.csv`.
1991	    let mut entry_cancelled_ttl: u64 = 0;
1992	    let mut entry_cancelled_wall_dead: u64 = 0;
1993	    let mut entry_cancelled_price_left: u64 = 0;
1994	    // F8b (В5/Р2): вход, снятый потолком ожидания подтверждения отмены, идёт
1995	    // той же строкой, что и прочие снятия, — причиной `CancelTimeout`.
1996	    let mut entry_cancelled_cancel_timeout: u64 = 0;
1997	    let mut exit_cancel_timeout: u64 = 0;
1998	    let mut orphan_fills: u64 = 0;
1999	    let mut spread_at_entry: Vec<f64> = Vec::new();
2000	    let mut busy_signal: Vec<usize> = Vec::new();
2001	    let mut submitted_signal: Vec<usize> = Vec::new();
2002	    let mut busy_wait_ns_max: i64 = 0;
2003	    let mut round_ns_max: i64 = 0;
2004	    let mut fill_signal: Vec<usize> = Vec::new();
2005	    let mut fill_reason: Vec<ExitReason> = Vec::new();
2006	    let mut fill_exit_ns: Vec<i64> = Vec::new();
2007	    let mut next_id = cfg.first_order_id;
2008	    // F8c: сироты переносятся между кругами суток (см. `drive_signal`).
2009	    let mut carry = OrphanCarry::NONE;
2010	    let mut incomplete = false;
2011	    let mut residual_flattened: u64 = 0;
2012	    // Форма занята, пока стратегия не вернулась в `Idle` после предыдущего
2013	    // сигнала (выход подтверждён или отмена входа подтверждена). Раньше
2014	    // занятость считалась только до `exit_ts` исполненного круга, а сигнал в
2015	    // хвосте круга или во время таймаута входа стартовал **с опозданием** —
2016	    // в момент освобождения, по устаревшему касанию (артефакт драйвера,
2017	    // 2026-09-18); теперь такой сигнал — промах «занято» в обоих драйверах.
2018	    let mut idle_ns: i64 = i64::MIN;
2019	
2020	    let miss_observation = |t0_ns: i64| FillObservation {
2021	        day_cluster: day_index_ns(t0_ns),
2022	        net_bps: 0.0,
2023	        filled: false,
2024	    };
2025	
2026	    for (sig_idx, sig) in order.iter().enumerate() {
2027	        if entry_side(sig.sigma).is_none() {
2028	            continue;
2029	        }
2030	        if sig.t0_ns < idle_ns {
2031	            busy_signal.push(sig_idx);
2032	            busy_wait_ns_max = busy_wait_ns_max.max(idle_ns.saturating_sub(sig.t0_ns));
2033	            misses.record(MissReason::PositionBusy);
2034	            observations.push(miss_observation(sig.t0_ns));
2035	            continue;
2036	        }
2037	        // Память кругов (G10): круг, уже посчитанный над тем же окном с тем же планом, берётся
2038	        // готовым; номера заявок и сироты продолжаются так, как если бы его считали здесь.
2039	        let recalled = memo.as_deref_mut().and_then(|m| m.recall(sig, next_id));
2040	        let step = match recalled {
2041	            Some((step, ids_used, carry_out)) => {
2042	                next_id = next_id.saturating_add(ids_used);
2043	                if let Some(c) = carry_out {
2044	                    carry = c;
2045	                }
2046	                step
2047	            }
2048	            None => {
2049	                let id_base = next_id;
2050	                let carry_base = carry;
2051	                let mut attempt = 0u32;
2052	                let step = loop {
2053	                    let r = source(sig, attempt, &mut |bot: &mut B| {
2054	                        drive_signal(bot, asset_no, sig, cfg, &mut next_id, &mut carry)
2055	                    })?;
2056	                    match r {
2057	                        Some((_, false)) => {
2058	                            next_id = id_base;
2059	                            carry = carry_base;
2060	                            attempt = attempt.saturating_add(1);
2061	                            HORIZON_RETRIES.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
2062	                        }
2063	                        Some((step, true)) => break Some(step),
2064	                        None => break None,
