25	/// Окно переноса, нс: сколько времени после полуночи D+1 ещё может
26	/// понадобиться, чтобы круг, открытый под конец суток D, дочитал свой выход.
27	/// Строится из чисел уже переданного прогона, не изобретённая константа:
28	/// наибольший потолок входа сетки (`--entry-ttl-secs`) плюс наибольший
29	/// `--deadline-secs` плюс небольшой запас на задержку исполнения (p95 RTT
30	/// тейкера — тот же параметр, что уже ограничивает выход рыночным ордером).
31	/// `EntryTtl::Touch` не добавляет времени: вход в этом режиме живёт не дольше
32	/// самого касания суток D (`touch.end_ms − touch.start_ms`), а касания —
33	/// собственные суток D, разбор их конца не выходит за пределы дня (F5,
34	/// `bounce_plan`). `EntryTtl::Wall` потолка не несёт (`entry_ttl_ns =
35	/// i64::MAX`, F5) — окно переноса с ним не построить, отказ, а не
36	/// изобретённое число.
37	pub(super) fn carry_window_ns(
38	    entry_ttls: &[EntryTtl],
39	    deadlines: &[u64],
40	    p95_taker_rtt_ns: i64,
41	) -> anyhow::Result<i64> {
42	    let mut max_entry_ttl_secs: i64 = 0;
43	    for ttl in entry_ttls {
44	        match ttl {
45	            EntryTtl::Touch => {}
46	            EntryTtl::Secs(secs) => max_entry_ttl_secs = max_entry_ttl_secs.max(*secs),
47	            EntryTtl::Wall => anyhow::bail!(
48	                "--carry-root: --entry-ttl-secs wall не ограничен по времени (F5, entry_ttl_ns = \
49	                 i64::MAX) — окно переноса не построить без числового потолка"
50	            ),
51	        }
52	    }
53	    let max_deadline_secs = deadlines.iter().copied().max().unwrap_or(0) as i64;
54	    Ok(max_entry_ttl_secs
55	        .saturating_add(max_deadline_secs)
56	        .saturating_mul(1_000_000_000)
57	        .saturating_add(p95_taker_rtt_ns))
58	}
