62	/// прежде — сетка замера ограничивает окно, не гоняется за произвольной
63	/// глубиной).
64	fn next_day_utc(day: &str) -> anyhow::Result<String> {
65	    let d = chrono::NaiveDate::parse_from_str(day, "%Y-%m-%d")
